import json
from datetime import datetime, timezone

STALE_DAYS = 7


def main(input_data):
    now_files = {f["path"]: f for f in input_data["files"]["files"]}
    try:
        before = json.loads(input_data["previous"].get("text") or "{}")
    except ValueError:
        before = {}
    first = not before
    new = sorted(p for p in now_files if p not in before)
    changed = sorted(p for p in now_files if p in before and before[p]["bytes"] != now_files[p]["bytes"])
    missing = sorted(p for p in before if p not in now_files)
    empty = sorted(p for p, f in now_files.items() if f["bytes"] == 0)
    total = sum(f["bytes"] for f in now_files.values())
    newest = max((f["modified"] for f in now_files.values()), default=None)
    warnings = []
    if not now_files:
        warnings.append("The backups folder is empty.")
    if newest:
        age = (datetime.now(timezone.utc) - datetime.fromisoformat(newest)).days
        if age >= STALE_DAYS:
            warnings.append("Nothing new has arrived for %d days." % age)
    if missing:
        warnings.append("%d file(s) that were here last time are gone." % len(missing))
    if empty:
        warnings.append("%d empty file(s)." % len(empty))
    lines = ["# Backup report (%s)\n" % datetime.now().astimezone().strftime("%Y-%m-%d %H:%M"),
             "%d files, %.1f MB." % (len(now_files), total / 1048576)]
    lines.append("First run: everything counts as new." if first else "Since the last run: %d new, %d changed, %d missing." % (len(new), len(changed), len(missing)))
    lines.append("\n## Needs attention\n" + ("\n".join("- " + w for w in warnings) if warnings else "Nothing."))
    for title, items in (("New", new), ("Changed", changed), ("Missing", missing), ("Empty", empty)):
        if items:
            lines.append("\n## " + title + "\n" + "\n".join("- " + p for p in items[:50]) + ("\n- ..." if len(items) > 50 else ""))
    manifest = {p: {"bytes": f["bytes"]} for p, f in now_files.items()}
    return {"text": "\n".join(lines) + "\n", "manifest": json.dumps(manifest)}
